import { useState, useCallback, useEffect } from "react";
import { DndProvider } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import update from "immutability-helper";
import StudyTool from "../StudyToolWrapper/StudyToolWrapper";
import { Link } from "react-router-dom";
import styles from "./StudySidebar.module.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faCamera,
  faClipboardCheck,
  faDownLeftAndUpRightToCenter,
  faHome,
  faHourglass,
  faImage,
  faMicrophone,
  faUpRightAndDownLeftFromCenter,
  faUsers,
  faVolumeHigh,
} from "@fortawesome/free-solid-svg-icons";
import { socket } from "../../../socket";

function FullScreenBtn () {
  const [isZoom, setIsZoom] = useState(false);

  useEffect(() => {
    if (!document.fullscreenElement && isZoom) {
      document.documentElement.requestFullscreen().catch((err) => {
        console.error("Fullscreen request failed:", err);
      });
    } else if (document.fullscreenElement) {
      document.exitFullscreen().catch((err) => {
        console.error("Exit fullscreen request failed:", err);
      });
    }
  }, [isZoom]);

  return (
    <div
    className={`${styles.studyTool} ${isZoom ? styles.clicked : ""}`}
    onClick={() => {
      setIsZoom((prev) => !prev);
    }}
  >
    <i>
      <FontAwesomeIcon
        icon={
          isZoom
            ? faDownLeftAndUpRightToCenter
            :  faUpRightAndDownLeftFromCenter
        }
      />
    </i>
    <div className={styles.hoverEl}>
      Full Screen
    </div>
  </div>
  )
};

function StudySidebar({
  isTimerModal,
  isPlannerModal,
  isTemplateModal,
  isGroupModal,
  isVolumeModal,
  isZoom,
  setIsTimerModal,
  setIsPlannerModal,
  setIsTemplateModal,
  setIsVolumeModal,
  setIsZoom,
  setIsViewGroups,
  setIsCam,
  setIsMic,
  isCam,
  isMic,
  bringSubjects
}) {
  const [items, setItems] = useState([
    {
      id: 0,
      element: (
        <Link
          to={"/dashboard/stats"}
          className={`${styles.studyTool} ${isTimerModal ? styles.clicked : ""
            }`}
          onClick={() => {
            bringSubjects();
            socket.emit('exitSession');
          }}
          style={{zIndex: 9}}
        >
          <i>
            <FontAwesomeIcon icon={faHome} />
          </i>
          <div className={styles.hoverEl}>
            to Home
          </div>
        </Link>
      ),
    },

    {
      id: 1,
      element: (
        <div
          className={`${styles.studyTool} ${isTimerModal ? styles.clicked : ""
            }`}
          onClick={() => {
            setIsTimerModal((prev) => !prev);
          }}
        >
          <i>
            <FontAwesomeIcon icon={faHourglass} />
          </i>
          <div className={styles.hoverEl}>
            Timer
          </div>
        </div>
      ),
    },

    {
      id: 2,
      element: (
        <div
          className={`${styles.studyTool} ${isPlannerModal ? styles.clicked : ""
            }`}
          onClick={() => {
            setIsPlannerModal((prev) => !prev);
          }}
        >
          <i>
            <FontAwesomeIcon icon={faClipboardCheck} />
          </i>
          <div className={styles.hoverEl}>
            Planner
          </div>
        </div>
      ),
    },

    {
      id: 3,
      element: (
        <div
          className={`${styles.studyTool} ${isCam ? styles.clicked : ""}`}
          onClick={() => {
            setIsCam((prev) => !prev);
          }}
        >
          <i>
            <FontAwesomeIcon icon={faCamera} />
          </i>
          <div className={styles.hoverEl}>
            Cam
          </div>
        </div>
      ),
    },

    {
      id: 4,
      element: (
        <div
          className={`${styles.studyTool} ${isMic ? styles.clicked : ""}`}
          onClick={() => {
            setIsMic((prev) => !prev);
          }}
        >
          <i>
            <FontAwesomeIcon icon={faMicrophone} />
          </i>
          <div className={styles.hoverEl}>
            Mic
          </div>
        </div>
      ),
    },

    {
      id: 5,
      element: (
        <div
          className={`${styles.studyTool} ${isTemplateModal ? styles.clicked : ""
            }`}
          onClick={() => {
            setIsTemplateModal((prev) => !prev);
          }}
        >
          <i>
            <FontAwesomeIcon icon={faImage} />
          </i>
          <div className={styles.hoverEl}>
            Themes
          </div>
        </div>
      ),
    },

    {
      id: 6,
      element: (
        <div
          className={`${styles.studyTool} ${isVolumeModal ? styles.clicked : ""
            }`}
          onClick={() => {
            setIsVolumeModal((prev) => !prev);
          }}
        >
          <i>
            <FontAwesomeIcon icon={faVolumeHigh} />
          </i>
          <div className={styles.hoverEl}>
            Sound
          </div>
        </div>
      ),
    },

    {
      id: 7,
      element: (
        <div
          className={`${styles.studyTool} ${isGroupModal ? styles.clicked : ""
            }`}
          onClick={() => {
            setIsViewGroups((prev) => !prev);
          }}
        >
          <i>
            <FontAwesomeIcon icon={faUsers} />
          </i>
          <div className={styles.hoverEl}>
            View Group
          </div>
        </div>
      ),
    },

    {
      id: 8,
      element: (
        <FullScreenBtn isZoom={isZoom} setIsZoom={setIsZoom} />
      ),
    },
  ]);

  const moveCard = useCallback((dragIndex, hoverIndex) => {
    setItems((prevItems) =>
      update(prevItems, {
        $splice: [
          [dragIndex, 1],
          [hoverIndex, 0, prevItems[dragIndex]],
        ],
      }),
    );
  }, []);

  const renderCard = useCallback((card, index, styles) => {
    return (
      <StudyTool
        key={card.id}
        index={index}
        id={card.id}
        element={card.element}
        moveCard={moveCard}
        styles={styles}
      />
    );
  }, []);

  return (
    <div className={styles.StudySidebar}>
      <DndProvider backend={HTML5Backend}>
        {items.map((card, i) => renderCard(card, i, styles))}
      </DndProvider>
    </div>
  );
}

export default StudySidebar;
